/**
 * OCN-ORDER-CHANGE-NOTICE round 20, I4: the hand-added "Order Change Notices" MY REQUESTS item is
 * gone. The item comes from the shared MY REQUESTS list (portalKind `order_change_notice`), so it
 * shows only when the salesperson's resolved portal kinds include the kind, like every other form.
 * Explicit assertions on purpose: the salesperson snapshot is regenerated by the coder, not here.
 */
import { describe, expect, it } from 'vitest';
import { MENU_SIDEBAR } from './menu.config';
import type { MenuConfig } from './types';
import { applyMenuAccess, type MenuAccess } from '@/lib/menu-access-filter';

const OCN_PATH = '/procurement-management/order-change-notices';
const PERMS = [
  'projects.projects.view_own',
  'sla_management.conversations.view_own',
  'procurement.stock_inquiries.view_own',
  'procurement.order_change_notices.view_own',
];

function access(portalKinds: string[]): MenuAccess {
  return {
    isSuperadmin: false,
    permissionSet: new Set(PERMS),
    isLoading: false,
    enabledModuleKeys: null,
    modulesLoading: false,
    salesperson: { portalKinds },
  } as MenuAccess;
}

function flat(items: MenuConfig): Array<{ title?: string; path?: string }> {
  return items.flatMap((i) => [{ title: i.title, path: i.path }, ...(i.children ? flat(i.children) : [])]);
}

describe('MY REQUESTS Order Change Notice item', () => {
  it('shows once, from the shared MY REQUESTS list, when the resolved portal kinds include it', () => {
    const items = flat(applyMenuAccess(MENU_SIDEBAR, access(['stock_inquiry', 'order_change_notice']))).filter(
      (i) => i.path === OCN_PATH,
    );
    expect(items).toHaveLength(1);
    expect(items[0].title).toMatch(/^Order Change Notices?$/);
  });

  it('is absent when the portal kinds do not include it, even with the view_own grant', () => {
    const items = flat(applyMenuAccess(MENU_SIDEBAR, access(['stock_inquiry'])));
    expect(items.filter((i) => i.path === OCN_PATH)).toEqual([]);
    expect(items.filter((i) => i.title === 'Order Change Notices')).toEqual([]);
  });

  it('keeps no hand-added salesperson item: the staff Procurement entry is the only "Order Change Notices"', () => {
    const handAdded = MENU_SIDEBAR.filter((i) => i.audience === 'salesperson' && i.title === 'Order Change Notices');
    expect(handAdded).toEqual([]);
  });
});
